import os
import requests

class AzureSpeechClient:
    def __init__(self, region: str, api_key: str = None):
        self.region = region
        self.api_key = api_key or os.environ.get("AZURE_SPEECH_KEY")
        if not self.api_key:
            raise ValueError("Azure Speech API key not provided and AZURE_SPEECH_KEY environment variable not set.")
        self.base_url = f"https://{self.region}.api.cognitive.microsoft.com/speechtotext/v3.1"

    def submit_transcription(self, display_name: str, locale: str, content_urls: list):
        headers = {'Ocp-Apim-Subscription-Key': self.api_key}
        json_payload = {
            'displayName': display_name,
            'locale': locale,
            'contentUrls': content_urls,
            'properties': {
                'wordLevelTimestampsEnabled': True,
                'diarizationEnabled': True,
            }
        }
        response = requests.post(f"{self.base_url}/transcriptions", headers=headers, json=json_payload, timeout=30)
        response.raise_for_status()
        return response.json()

    def get_transcription(self, transcription_id: str):
        headers = {'Ocp-Apim-Subscription-Key': self.api_key}
        response = requests.get(f"{self.base_url}/transcriptions/{transcription_id}", headers=headers, timeout=30)
        response.raise_for_status()
        return response.json()

    def get_transcription_files(self, transcription_id: str):
        headers = {'Ocp-Apim-Subscription-Key': self.api_key}
        response = requests.get(f"{self.base_url}/transcriptions/{transcription_id}/files", headers=headers, timeout=30)
        response.raise_for_status()
        return response.json()

    def get_file_content(self, content_url: str):
        headers = {'Ocp-Apim-Subscription-Key': self.api_key}
        response = requests.get(content_url, headers=headers, timeout=30)
        response.raise_for_status()
        return response.json()

import time
import os
from speech_client import AzureSpeechClient
from speech_models import TranscriptionResponse, TranscriptionResult

def poll_transcription(job_id: str, region: str, api_key: str = None, timeout_seconds: int = 3600):
    client = AzureSpeechClient(region=region, api_key=api_key)
    start_time = time.time()

    while True:
        if time.time() - start_time > timeout_seconds:
            raise TimeoutError("Transcription polling timed out.")

        response_json = client.get_transcription(job_id.split('/')[-1]) # Extract job_id from the full URL
        response = TranscriptionResponse(**response_json)

        if response.status == "Succeeded":
            # Fetch files associated with the transcription
            files_json = client.get_transcription_files(job_id.split('/')[-1])
            transcript_file_url = None
            for file_info in files_json.get('values', []):
                if file_info.get('kind') == "Transcription":
                    transcript_file_url = file_info['links']['contentUrl']
                    break

            if transcript_file_url:
                transcript_content = client.get_file_content(transcript_file_url)
                return TranscriptionResult(**transcript_content)
            else:
                raise ValueError("Transcription succeeded but no transcript file found.")

        elif response.status in ["Failed", "Cancelled"]:
            raise RuntimeError(f"Transcription job {job_id} {response.status}.")

        time.sleep(10) # Poll every 10 seconds

from typing import List, Dict
from speech_models import TranscriptionResult

def get_diarized_transcript(transcription_result: TranscriptionResult) -> List[Dict]:
    diarized_segments = []
    if transcription_result and transcription_result.recognized_phrases:
        for phrase in transcription_result.recognized_phrases:
            speaker_id = phrase.get('speaker') # Azure Speech output includes 'speaker' property if diarization is enabled
            text = phrase.get('display')
            offset_ms = phrase.get('offsetInTicks', 0) / 10000 # Convert ticks to milliseconds
            duration_ms = phrase.get('durationInTicks', 0) / 10000 # Convert ticks to milliseconds
            if speaker_id is not None and text:
                diarized_segments.append({
                    "speaker_id": speaker_id,
                    "text": text,
                    "offset_ms": offset_ms,
                    "duration_ms": duration_ms
                })
    return diarized_segments

from typing import List, Dict
from speech_models import TranscriptionResult

def get_timestamped_transcript(transcription_result: TranscriptionResult) -> List[Dict]:
    timestamped_words = []
    if transcription_result and transcription_result.recognized_phrases:
        for phrase in transcription_result.recognized_phrases:
            for word in phrase.get('words', []):
                text = word.get('word')
                offset_ms = word.get('offsetInTicks', 0) / 10000
                duration_ms = word.get('durationInTicks', 0) / 10000
                if text:
                    timestamped_words.append({
                        "word": text,
                        "offset_ms": offset_ms,
                        "duration_ms": duration_ms
                    })
    return timestamped_words

import os
from google.cloud import translate_v3 as translate

def translate_transcript_segments(text_segments: List[str], target_language_code: str, project_id: str = None) -> List[str]:
    project_id = project_id or os.environ.get("GOOGLE_CLOUD_PROJECT")
    if not project_id:
        raise ValueError("Google Cloud Project ID not provided and GOOGLE_CLOUD_PROJECT environment variable not set.")

    client = translate.TranslationServiceClient()
    parent = f"projects/{project_id}/locations/global"

    translated_texts = []
    for text in text_segments:
        response = client.translate_text(
            request={
                "parent": parent,
                "contents": [text],
                "target_language_code": target_language_code,
            }
        )
        for translation in response.translations:
            translated_texts.append(translation.translated_text)
    return translated_texts
